class Solution:
    def numSubmat(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        height = [[0]*n for _ in range(m)]
        for j in range(n):
            for i in range(m):
                if mat[i][j] == 1:
                    height[i][j] = height[i-1][j] + 1 if i > 0 else 1

        # Then for each cell, try to count rectangles ending at that cell
        result = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 1:
                    min_height = height[i][j]
                    k = j
                    while k >= 0 and mat[i][k] == 1:
                        min_height = min(min_height, height[i][k])
                        result += min_height
                        k -= 1
        return result
